#include <stdlib.h>
#include <stdbool.h>
typedef struct Node211{struct Node211*c[26];bool end;}Node211;typedef struct{Node211*r;}WordDictionary;static Node211*newn(){return calloc(1,sizeof(Node211));}WordDictionary* wordDictionaryCreate(){WordDictionary*w=malloc(sizeof(*w));w->r=newn();return w;}void wordDictionaryAddWord(WordDictionary*w,char*s){Node211*p=w->r;for(int i=0;s[i];i++){int k=s[i]-'a';if(!p->c[k])p->c[k]=newn();p=p->c[k];}p->end=true;}static bool f(Node211*p,char*s){if(!p)return false;if(!*s)return p->end;if(*s=='.'){for(int i=0;i<26;i++)if(f(p->c[i],s+1))return true;return false;}return f(p->c[*s-'a'],s+1);}bool wordDictionarySearch(WordDictionary*w,char*s){return f(w->r,s);}static void freen(Node211*p){if(!p)return;for(int i=0;i<26;i++)freen(p->c[i]);free(p);}void wordDictionaryFree(WordDictionary*w){freen(w->r);free(w);}
